"""Browser command centre for the real Gazebo Harmonic F450 renderer.

The large viewport deliberately embeds a separately rendered Gazebo GUI. It
never manufactures a 3D flight from browser data: only the GPU host makes the
renderer available. SITL telemetry and the mission map support that scene.
"""
from __future__ import annotations

import json
import os

from fastapi.responses import HTMLResponse


# The permanent host should set relative reverse-proxy paths. The Lightning URL
# remains only as a backwards-compatible control fallback during migration.
CONTROL_URL = os.environ.get(
    "GAZEBO_CONTROL_URL",
    "https://8000-01m08b33gb41qz7hynmx9c8x8t.cloudspaces.litng.ai",
).rstrip("/")
VIEW_URL = os.environ.get("GAZEBO_VIEW_URL", "").strip()


def attach(app):
    # Replace only older flight viewers. Hardware routes and their F450 assets
    # are not inspected, modified, or removed here.
    for route in list(app.router.routes):
        if getattr(route, "path", None) in {"/drone-flight", "/drone-flight/3d"}:
            app.router.routes.remove(route)

    @app.get("/drone-flight", response_class=HTMLResponse)
    @app.get("/drone-flight/3d", response_class=HTMLResponse)
    def gazebo_flight_page():
        return (
            HTML.replace("__GAZEBO_CONTROL_URL__", json.dumps(CONTROL_URL))
            .replace("__GAZEBO_VIEW_URL__", json.dumps(VIEW_URL))
        )


HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>VanniKawachh | Live Gazebo F450</title>
<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" integrity="sha256-p4NxAoJBhIINfQxkM6uQ3nZ6D/9cU9e6o5h1K0P7v+I=" crossorigin="">
<style>
:root{--bg:#060d12;--surface:#0a171eef;--surface2:#0b2029;--line:#284a56;--text:#edf8fa;--muted:#91aab4;--green:#35e1b2;--amber:#ffbd5a;--cyan:#57ddff}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font:13px Inter,Segoe UI,Arial,sans-serif}#app{display:grid;grid-template-columns:minmax(0,1fr) 360px;grid-template-rows:minmax(500px,68vh) minmax(250px,32vh);min-height:100vh}.viewport{position:relative;min-width:0;background:#09141b;overflow:hidden}.viewport iframe{width:100%;height:100%;border:0;background:#09141b}.empty{position:absolute;inset:0;display:grid;place-items:center;padding:30px;background:radial-gradient(circle at 50% 30%,#153644,#071116 63%);text-align:center}.empty-box{max-width:520px}.empty h1{margin:0 0 9px;font-size:26px}.empty p{margin:7px auto;color:var(--muted);line-height:1.55}.empty code{color:#b9eefa}.eyebrow{color:var(--cyan);font-size:10px;font-weight:900;letter-spacing:.16em}.scene-chip{position:absolute;z-index:2;top:15px;left:15px;padding:8px 10px;background:#06131bd9;border:1px solid var(--line);border-radius:8px;font-size:11px;font-weight:800}.scene-chip i{display:inline-block;width:8px;height:8px;margin-right:7px;border-radius:50%;background:var(--amber)}.scene-chip.live i{background:var(--green);box-shadow:0 0 12px var(--green)}.map-wrap{position:relative;min-width:0;border-top:1px solid var(--line)}#map{position:absolute;inset:0;background:#132832}.map-title{position:absolute;z-index:500;top:13px;left:13px;padding:7px 9px;border:1px solid var(--line);border-radius:7px;background:#06131bdf;font-size:11px;font-weight:800}.side{grid-row:1 / span 2;padding:15px;background:var(--surface);border-left:1px solid var(--line);overflow:auto}.side h2{margin:0;font-size:21px}.sub{margin:5px 0 14px;color:var(--muted);font-size:11px;line-height:1.45}.state{display:flex;gap:8px;align-items:center;margin:11px 0 13px;font-weight:900}.state i{width:9px;height:9px;border-radius:50%;background:var(--amber)}.state.live i{background:var(--green);box-shadow:0 0 12px var(--green)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:7px}.metric{padding:9px;background:var(--surface2);border-radius:8px}.metric span{display:block;color:var(--muted);font-size:9px;letter-spacing:.1em}.metric b{display:block;margin-top:4px;font-size:16px;font-variant-numeric:tabular-nums}.section{margin-top:13px;padding-top:12px;border-top:1px solid #213d47}.row{display:flex;justify-content:space-between;gap:8px;margin:7px 0}.row span{color:var(--muted)}.row b{text-align:right}.actions{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:14px}.btn{border:1px solid var(--line);border-radius:8px;padding:10px;background:#102833;color:var(--text);font:inherit;font-weight:900;cursor:pointer}.btn.primary{background:#0b3025;border-color:#2b795f}.btn.warn{background:#2c2013;border-color:#74542a}.btn:disabled{opacity:.45;cursor:wait}#notice{margin:12px 0 0;color:var(--muted);font-size:10px;line-height:1.45}.drone-pin{font-size:28px;line-height:28px;color:#f6fcfd;text-shadow:0 2px 5px #000;transform-origin:50% 50%}.leaflet-control-attribution{background:#07131bcc!important;color:#b3cbd2!important}.leaflet-control-attribution a{color:#7edff6!important}@media(max-width:900px){#app{grid-template-columns:1fr;grid-template-rows:minmax(440px,62vh) 330px auto}.side{grid-row:auto;border-left:0;border-top:1px solid var(--line);overflow:visible}.viewport{min-height:440px}.map-wrap{min-height:330px}}@media(max-width:440px){.side{padding:12px}}
</style></head><body>
<main id="app"><section class="viewport" aria-label="Live Gazebo Harmonic renderer"><div id="scene-chip" class="scene-chip"><i></i><span id="scene-label">GAZEBO RENDERER OFFLINE</span></div><iframe id="gazebo-view" title="Live Gazebo Harmonic F450 renderer" allow="fullscreen"></iframe><div id="renderer-empty" class="empty"><div class="empty-box"><div class="eyebrow">AUTHORITATIVE 3D PHYSICS VIEW</div><h1>Gazebo renderer is not configured on this host</h1><p>This viewport is reserved for the actual GPU-rendered Gazebo Harmonic F450 scene: launch, flight, hover, payload drop and landing. It is intentionally blank until the renderer stream is available.</p><p>On the permanent GPU host, configure <code>GAZEBO_VIEW_URL=/gazebo-ui/vnc.html?autoconnect=true&amp;path=gazebo-ui/websockify</code>.</p></div></div></section><section class="map-wrap" aria-label="Live flight mission map"><div id="map"></div><div class="map-title">LIVE MISSION MAP <span id="map-source">/ waiting for Gazebo</span></div></section><aside class="side"><h2>Gazebo F450 Flight</h2><div class="sub">Actual Gazebo Harmonic rendering is the primary view. This panel reads only live ArduPilot SITL + Gazebo telemetry; browser simulation is rejected.</div><div id="live-state" class="state"><i></i><span>Waiting for real Gazebo telemetry</span></div><div class="grid"><div class="metric"><span>FLIGHT MODE</span><b id="mode">--</b></div><div class="metric"><span>ALTITUDE AGL</span><b id="alt">--</b></div><div class="metric"><span>GROUND SPEED</span><b id="speed">--</b></div><div class="metric"><span>MOTORS</span><b id="motors">--</b></div></div><div class="section"><div class="row"><span>Source</span><b id="source">Awaiting bridge</b></div><div class="row"><span>Mission</span><b id="mission">--</b></div><div class="row"><span>Route samples</span><b id="samples">0</b></div><div class="row"><span>Payload</span><b id="payload">Secured</b></div></div><div class="actions"><button class="btn primary" id="start">Start runtime</button><button class="btn" id="follow">Map follow: on</button><button class="btn" id="fit">Fit mission</button><button class="btn warn" id="stop">Stop runtime</button></div><p id="notice">The renderer starts on the GPU host; it is not a browser-generated 3D animation.</p></aside></main>
<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" integrity="sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=" crossorigin=""></script>
<script>
(()=>{const CONTROL=__GAZEBO_CONTROL_URL__,VIEW=__GAZEBO_VIEW_URL__,$=id=>document.getElementById(id),map=L.map('map',{zoomControl:false,worldCopyJump:true}).setView([21.1458,79.0882],13);L.control.zoom({position:'bottomleft'}).addTo(map);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxZoom:19,opacity:.78,attribution:'Satellite tiles &copy; Esri'}).addTo(map);const icon=L.divIcon({className:'',html:'<div class="drone-pin">&#9650;</div>',iconSize:[30,30],iconAnchor:[15,15]}),drone=L.marker([21.1458,79.0882],{icon,opacity:0,keyboard:false}).addTo(map),trail=L.polyline([],{color:'#57ddff',weight:4,opacity:.9}).addTo(map);let home,target,lastPoint,follow=true,framed=false;const isNum=x=>typeof x==='number'&&Number.isFinite(x),fmt=(x,unit)=>isNum(x)?x.toFixed(1)+unit:'--';function setLive(text,live){$('live-state').className='state '+(live?'live':'');$('live-state').lastElementChild.textContent=text;$('map-source').textContent='/ '+(live?'live Gazebo':'waiting for Gazebo')}function marker(kind,point){if(!Array.isArray(point)||point.length!==2)return;const old=kind==='home'?home:target,color=kind==='home'?'#35e1b2':'#ffbd5a',label=kind==='home'?'Launch / RTL home':'Mission target',next=L.circleMarker(point,{radius:7,color,weight:2,fillColor:color,fillOpacity:.85}).bindTooltip(label);if(old)map.removeLayer(old);if(kind==='home')home=next.addTo(map);else target=next.addTo(map)}function fit(){const items=[drone,home,target].filter(Boolean);if(items.length)map.fitBounds(L.featureGroup(items).getBounds(),{padding:[60,60],maxZoom:16})}function apply(payload){if(!payload||payload.source!=='ARDUPILOT_SITL_GAZEBO'||!payload.connected||!payload.state){setLive('Waiting for real Gazebo telemetry',false);$('source').textContent=payload&&payload.source||'Unavailable';return}const d=payload.state;if(!isNum(d.lat)||!isNum(d.lon)){setLive('Bridge connected; waiting for GPS',false);return}const point=[d.lat,d.lon],changed=!lastPoint||Math.abs(point[0]-lastPoint[0])>1e-7||Math.abs(point[1]-lastPoint[1])>1e-7;if(changed){trail.addLatLng(point);lastPoint=point}drone.setLatLng(point).setOpacity(1);const markerEl=drone.getElement(),heading=isNum(d.heading_deg)?d.heading_deg:0;if(markerEl){const arrow=markerEl.querySelector('.drone-pin');if(arrow)arrow.style.transform='rotate('+heading+'deg)'}marker('home',d.home);marker('target',d.target);if(!framed&&(home||target)){fit();framed=true}if(follow)map.panTo(point,{animate:true,duration:.45});$('mode').textContent=d.flight_mode||d.state||'--';$('alt').textContent=fmt(d.altitude_m,' m');$('speed').textContent=fmt(d.ground_speed_ms,' m/s');$('motors').textContent=d.motors_active?'Active':'Idle';$('source').textContent=payload.source;$('mission').textContent=d.mission_id||'--';$('samples').textContent=trail.getLatLngs().length;$('payload').textContent=d.kit_dropped?'Delivered':'Secured';setLive((d.armed?'Armed':'Disarmed')+' / '+(d.flight_mode||d.state||'Ready'),true);$('notice').textContent='Live SITL bridge update / '+new Date().toLocaleTimeString()}async function poll(){try{apply(await (await fetch('/sitl-status',{cache:'no-store'})).json())}catch(e){setLive('Hub telemetry temporarily unavailable',false)}setTimeout(poll,1200)}async function control(path,method){if(!CONTROL){$('notice').textContent='No runtime control URL configured for this host.';return}const button=path==='/start'?$('start'):$('stop');button.disabled=true;try{const response=await fetch(CONTROL+path,{method,mode:'cors'});if(!response.ok)throw Error('HTTP '+response.status);$('notice').textContent='Runtime: '+await response.text()}catch(e){$('notice').textContent='Runtime control unavailable: '+e.message}finally{button.disabled=false}}function loadRenderer(){if(!VIEW)return;$('gazebo-view').src=VIEW;$('gazebo-view').addEventListener('load',()=>{$('renderer-empty').style.display='none';$('scene-chip').classList.add('live');$('scene-label').textContent='LIVE GAZEBO RENDERER'})}loadRenderer();$('start').onclick=()=>control('/start','POST');$('stop').onclick=()=>control('/stop','POST');$('fit').onclick=fit;$('follow').onclick=()=>{follow=!follow;$('follow').textContent='Map follow: '+(follow?'on':'off')};addEventListener('resize',()=>map.invalidateSize());setTimeout(()=>map.invalidateSize(),200);poll()})();
</script></body></html>'''
